using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.EventSystems;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseRightClickPreviewDice", menuName = "Data/Battle/Actions/OnMouseRightClick Preview Dice")]
public class OnMouseRightClickPreviewDice : Action
{
	[Header("Events")]
	[SerializeField]
	private DiceEvent OnShowDicePreview;

	[SerializeField]
	private VoidEvent OnHideDicePreview;

	[Header("Tooltip")]
	[SerializeField]
	private GameObjectReference actionDescriptionActionOwnerReference;

	[NonSerialized]
	private bool dicePreviewOn;

	private float timer;

	private GameObject dieTouched;

	public bool DicePreviewOn => dicePreviewOn;

	public void OnReset()
	{
		timer = 0f;
		dieTouched = null;
	}

	public override void Execute(float d)
	{
		bool flag = false;
		if (Input.GetMouseButtonDown(1))
		{
			flag = true;
		}
		if (flag)
		{
			List<DiceInstance> handDices = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;
			for (int i = 0; i < handDices.Count; i++)
			{
				if (handDices[i].IsFollowingMouse())
				{
					handDices[i].StopFollowingMouse();
					handDices[i].UpdateTransitionOutlineLayer();
					return;
				}
			}
			List<RuneInstance> list = base.inputManager.RunesPanelInitializer.RuneInstances.Duplicate();
			list.RemoveNullObjects();
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].IsFollowingMouse())
				{
					list[j].StopFollowingMouse();
					list[j].RemoveHighlightRuneInstance();
					return;
				}
			}
			List<DiceInstance> enemiesDiceInstances = ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.GetEnemiesDiceInstances();
			enemiesDiceInstances.AddRange(ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.GetSentinelsDiceInstances());
			for (int k = 0; k < enemiesDiceInstances.Count; k++)
			{
				if (enemiesDiceInstances[k].IsFollowingMouse())
				{
					enemiesDiceInstances[k].StopFollowingMouse();
					return;
				}
			}
			List<RaycastResult> uIObjectsOverMouse = MouseInputUtility.GetUIObjectsOverMouse();
			if (uIObjectsOverMouse.Count > 0)
			{
				DiceInstance componentInParent = uIObjectsOverMouse.First().gameObject.GetComponentInParent<DiceInstance>();
				if (componentInParent != null)
				{
					actionDescriptionActionOwnerReference.Set(componentInParent.ActionOwner);
					OnShowDicePreview.Raise(componentInParent.Dice);
					dicePreviewOn = true;
					return;
				}
			}
			if (dicePreviewOn)
			{
				TurnOffDicePreview();
			}
		}
		if (Input.GetMouseButtonDown(0) && dicePreviewOn)
		{
			TurnOffDicePreview();
		}
	}

	private void TurnOffDicePreview()
	{
		actionDescriptionActionOwnerReference.Set(null);
		dicePreviewOn = false;
		OnHideDicePreview.Raise();
	}

	public void TryTurnOffDicePreview()
	{
		if (dicePreviewOn)
		{
			TurnOffDicePreview();
		}
	}
}
